scratchpad.current_owl_draft:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#UNEDIFACTInvoiceStory>
    a owl:Ontology ;
    rdfs:label "UN/EDIFACT Invoice Ontology"@en ;
    rdfs:comment "A deep and structured ontology for UN/EDIFACT invoice messages, roles, and technical alignment, supporting EN 16931 and P2P-O alignment."@en .

#################################################################
# Classes
#################################################################
:Interchange a owl:Class ;
    rdfs:label "Interchange"@en ;
    rdfs:comment "The envelope for EDIFACT messages, containing one or more messages."@en .

:Message a owl:Class ;
    rdfs:label "Message"@en ;
    rdfs:comment "A generic EDIFACT message."@en .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message"@en ;
    rdfs:comment "An EDIFACT invoice message (e.g., INVOIC) containing header, detail, and summary sections."@en .

:Segment a owl:Class ;
    rdfs:label "Segment"@en ;
    rdfs:comment "A segment within an EDIFACT message, such as BGM or NAD."@en .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Header Section"@en ;
    rdfs:comment "The header section of an invoice message, containing document dates and reference numbers."@en .

:DetailSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Detail Section"@en ;
    rdfs:comment "The detail section of an invoice message, listing line items."@en .

:SummarySection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Summary Section"@en ;
    rdfs:comment "The summary section of an invoice message, providing total tax and invoice amounts."@en .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element"@en ;
    rdfs:comment "A composite data element within a segment, grouping simple elements."@en .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element"@en ;
    rdfs:comment "A simple data element representing atomic data within a composite element."@en .

:Delimiter a owl:Class ;
    rdfs:label "Delimiter"@en ;
    rdfs:comment "A delimiter character used in EDIFACT messages, such as plus sign or colon."@en .

:Organization a owl:Class ;
    rdfs:label "Organization"@en ;
    rdfs:comment "An organization involved in an invoice, possibly playing multiple roles."@en .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role"@en ;
    rdfs:comment "A general role played by an organization in an invoice context."@en ;
    rdfs:seeAlso :RoleAssignment .

:PartyRole a owl:Class ;
    rdfs:label "Party Role"@en ;
    rdfs:comment "A specific party role in the invoice, such as buyer or delivery party."@en ;
    owl:disjointUnionOf ( :BuyerRole :DeliveryPartyRole ) .

:BuyerRole a owl:Class ;
    rdfs:subClassOf :PartyRole ;
    rdfs:label "Buyer Role"@en ;
    rdfs:comment "The buyer role in an invoice transaction."@en .

:DeliveryPartyRole a owl:Class ;
    rdfs:subClassOf :PartyRole ;
    rdfs:label "Delivery Party Role"@en ;
    rdfs:comment "The delivery party role in an invoice transaction."@en .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment"@en ;
    rdfs:comment "A pivot class for reifying the assignment of an organization to a party role within a specific invoice."@en ;
    rdfs:seeAlso :AgentRole .

:Address a owl:Class ;
    rdfs:label "Address"@en ;
    rdfs:comment "A general address for an organization."@en .

:HeadquartersAddress a owl:Class ;
    rdfs:subClassOf :Address ;
    rdfs:label "Headquarters Address"@en ;
    rdfs:comment "An organization's headquarters address."@en .

:WarehouseAddress a owl:Class ;
    rdfs:subClassOf :Address ;
    rdfs:label "Warehouse Address"@en ;
    rdfs:comment "An organization's warehouse address."@en .

:Identifier a owl:Class ;
    rdfs:label "Identifier"@en ;
    rdfs:comment "An identifier such as a Global Location Number (GLN)."@en .

:Item a owl:Class ;
    rdfs:label "Item"@en ;
    rdfs:comment "An item sold in the invoice."@en .

:Price a owl:Class ;
    rdfs:label "Price"@en ;
    rdfs:comment "A price assigned to an item in the invoice."@en .

:Quantity a owl:Class ;
    rdfs:label "Quantity"@en ;
    rdfs:comment "A quantity of an item in the invoice."@en .

:Tax a owl:Class ;
    rdfs:label "Tax"@en ;
    rdfs:comment "A tax amount in the summary section of the invoice."@en .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process"@en ;
    rdfs:comment "A business process to which an invoice can be assigned."@en .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint"@en ;
    rdfs:comment "A constraint for validating invoice contents, e.g., SHACL rules."@en .

:EDIFACTDirectory a owl:Class ;
    rdfs:label "EDIFACT Directory"@en ;
    rdfs:comment "A directory of mandatory codes and elements for EDIFACT validation (e.g., D96A)."@en ;
    rdfs:seeAlso :Segment , :CompositeDataElement , :SimpleDataElement .

:EN16931Alignment a owl:Class ;
    rdfs:label "EN 16931 Alignment"@en ;
    rdfs:comment "Alignment with the European Standard EN 16931-1 for semantic interoperability."@en .

:P2POAlignment a owl:Class ;
    rdfs:label "P2P-O Alignment"@en ;
    rdfs:comment "Alignment with the Purchase-to-Pay Ontology (P2P-O)."@en .

#################################################################
# Object Properties with owl:inverseOf
#################################################################
:hasMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Interchange ;
    rdfs:range :Message ;
    rdfs:label "has message"@en ;
    rdfs:comment "Links an interchange envelope to its contained message."@en ;
    owl:inverseOf :isMessageOf .

:isMessageOf a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Interchange ;
    rdfs:label "is message of"@en ;
    rdfs:comment "Inverse of hasMessage."@en ;
    owl:inverseOf :hasMessage .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment"@en ;
    rdfs:comment "Links a message to its segments."@en ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "is segment of"@en ;
    rdfs:comment "Inverse of hasSegment."@en ;
    owl:inverseOf :hasSegment .

:hasHeaderSection a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :HeaderSection ;
    rdfs:label "has header section"@en ;
    rdfs:comment "Links an invoice message to its header section."@en ;
    owl:inverseOf :isHeaderSectionOf .

:isHeaderSectionOf a owl:ObjectProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is header section of"@en ;
    rdfs:comment "Inverse of hasHeaderSection."@en ;
    owl:inverseOf :hasHeaderSection .

:hasDetailSection a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :DetailSection ;
    rdfs:label "has detail section"@en ;
    rdfs:comment "Links an invoice message to its detail section."@en ;
    owl:inverseOf :isDetailSectionOf .

:isDetailSectionOf a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is detail section of"@en ;
    rdfs:comment "Inverse of hasDetailSection."@en ;
    owl:inverseOf :hasDetailSection .

:hasSummarySection a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :SummarySection ;
    rdfs:label "has summary section"@en ;
    rdfs:comment "Links an invoice message to its summary section."@en ;
    owl:inverseOf :isSummarySectionOf .

:isSummarySectionOf a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is summary section of"@en ;
    rdfs:comment "Inverse of hasSummarySection."@en ;
    owl:inverseOf :hasSummarySection .

:containsCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "contains composite element"@en ;
    rdfs:comment "Links a segment to its composite data elements."@en ;
    owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    rdfs:label "is composite element of"@en ;
    rdfs:comment "Inverse of containsCompositeElement."@en ;
    owl:inverseOf :containsCompositeElement .

:containsSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "contains simple element"@en ;
    rdfs:comment "Links a composite data element to its simple elements."@en ;
    owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "is simple element of"@en ;
    rdfs:comment "Inverse of containsSimpleElement."@en ;
    owl:inverseOf :containsSimpleElement .

:hasDelimiter a owl:ObjectProperty ;
    rdfs:domain :Interchange ;
    rdfs:range :Delimiter ;
    rdfs:label "has delimiter"@en ;
    rdfs:comment "Links an interchange to its delimiters."@en ;
    owl:inverseOf :isDelimiterOf .

:isDelimiterOf a owl:ObjectProperty ;
    rdfs:domain :Delimiter ;
    rdfs:range :Interchange ;
    rdfs:label "is delimiter of"@en ;
    rdfs:comment "Inverse of hasDelimiter."@en ;
    owl:inverseOf :hasDelimiter .

:playsRole a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment ;
    rdfs:label "plays role"@en ;
    rdfs:comment "Links an organization to its role assignments in invoices."@en ;
    owl:inverseOf :isRolePlayedBy .

:isRolePlayedBy a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "is role played by"@en ;
    rdfs:comment "Inverse of playsRole."@en ;
    owl:inverseOf :playsRole .

:hasRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :PartyRole ;
    rdfs:label "has role"@en ;
    rdfs:comment "Links a role assignment to a party role (buyer, delivery party, etc.)."@en ;
    owl:inverseOf :isRoleOf .

:isRoleOf a owl:ObjectProperty ;
    rdfs:domain :PartyRole ;
    rdfs:range :RoleAssignment ;
    rdfs:label "is role of"@en ;
    rdfs:comment "Inverse of hasRole."@en ;
    owl:inverseOf :hasRole .

:inInvoice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "in invoice"@en ;
    rdfs:comment "Links a role assignment to the invoice in which it occurs."@en ;
    owl:inverseOf :hasRoleAssignment .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :RoleAssignment ;
    rdfs:label "has role assignment"@en ;
    rdfs:comment "Inverse of inInvoice."@en ;
    owl:inverseOf :inInvoice .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address"@en ;
    rdfs:comment "Links an organization to its addresses."@en ;
    owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is address of"@en ;
    rdfs:comment "Inverse of hasAddress."@en ;
    owl:inverseOf :hasAddress .

:hasHeadquarters a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :HeadquartersAddress ;
    rdfs:label "has headquarters"@en ;
    rdfs:comment "Links an organization to its headquarters address."@en ;
    owl:inverseOf :isHeadquartersOf .

:isHeadquartersOf a owl:ObjectProperty ;
    rdfs:domain :HeadquartersAddress ;
    rdfs:range :Organization ;
    rdfs:label "is headquarters of"@en ;
    rdfs:comment "Inverse of hasHeadquarters."@en ;
    owl:inverseOf :hasHeadquarters .

:hasWarehouse a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :WarehouseAddress ;
    rdfs:label "has warehouse"@en ;
    rdfs:comment "Links an organization to its warehouse address."@en ;
    owl:inverseOf :isWarehouseOf .

:isWarehouseOf a owl:ObjectProperty ;
    rdfs:domain :WarehouseAddress ;
    rdfs:range :Organization ;
    rdfs:label "is warehouse of"@en ;
    rdfs:comment "Inverse of hasWarehouse."@en ;
    owl:inverseOf :hasWarehouse .

:hasIdentifier a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier"@en ;
    rdfs:comment "Links an organization to its identifier (e.g., GLN)."@en ;
    owl:inverseOf :isIdentifierOf .

:isIdentifierOf a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    rdfs:label "is identifier of"@en ;
    rdfs:comment "Inverse of hasIdentifier."@en ;
    owl:inverseOf :hasIdentifier .

:hasItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :Item ;
    rdfs:label "has item"@en ;
    rdfs:comment "Links a detail section to its items."@en ;
    owl:inverseOf :isItemOf .

:isItemOf a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :DetailSection ;
    rdfs:label "is item of"@en ;
    rdfs:comment "Inverse of hasItem."@en ;
    owl:inverseOf :hasItem .

:hasPrice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range :Price ;
    rdfs:label "has price"@en ;
    rdfs:comment "Links an item to its price."@en ;
    owl:inverseOf :isPriceOf .

:isPriceOf a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :Item ;
    rdfs:label "is price of"@en ;
    rdfs:comment "Inverse of hasPrice."@en ;
    owl:inverseOf :hasPrice .

:hasQuantity a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range :Quantity ;
    rdfs:label "has quantity"@en ;
    rdfs:comment "Links an item to its quantity."@en ;
    owl:inverseOf :isQuantityOf .

:isQuantityOf a owl:ObjectProperty ;
    rdfs:domain :Quantity ;
    rdfs:range :Item ;
    rdfs:label "is quantity of"@en ;
    rdfs:comment "Inverse of hasQuantity."@en ;
    owl:inverseOf :hasQuantity .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax ;
    rdfs:label "has tax"@en ;
    rdfs:comment "Links a summary section to its taxes."@en ;
    owl:inverseOf :isTaxOf .

:isTaxOf a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :SummarySection ;
    rdfs:label "is tax of"@en ;
    rdfs:comment "Inverse of hasTax."@en ;
    owl:inverseOf :hasTax .

:hasMandatoryIdentifier a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Identifier ;
    rdfs:label "has mandatory identifier"@en ;
    rdfs:comment "Links an invoice message to its mandatory identifiers as required by the directory."@en ;
    owl:inverseOf :isMandatoryIdentifierOf .

:isMandatoryIdentifierOf a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is mandatory identifier of"@en ;
    rdfs:comment "Inverse of hasMandatoryIdentifier."@en ;
    owl:inverseOf :hasMandatoryIdentifier .

:isAlignedWithEN16931 a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :EN16931Alignment ;
    rdfs:label "is aligned with EN 16931"@en ;
    rdfs:comment "Indicates EN 16931-1 alignment of the invoice message."@en ;
    owl:inverseOf :alignsEN16931 .

:alignsEN16931 a owl:ObjectProperty ;
    rdfs:domain :EN16931Alignment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "aligns EN 16931"@en ;
    rdfs:comment "Inverse of isAlignedWithEN16931."@en ;
    owl:inverseOf :isAlignedWithEN16931 .

:isAlignedWithP2PO a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :P2POAlignment ;
    rdfs:label "is aligned with P2P-O"@en ;
    rdfs:comment "Indicates P2P-O alignment of the invoice message."@en ;
    owl:inverseOf :alignsP2PO .

:alignsP2PO a owl:ObjectProperty ;
    rdfs:domain :P2POAlignment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "aligns P2P-O"@en ;
    rdfs:comment "Inverse of isAlignedWithP2PO."@en ;
    owl:inverseOf :isAlignedWithP2PO .

:isValidatedBy a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint ;
    rdfs:label "is validated by"@en ;
    rdfs:comment "Links an invoice message to validation constraints such as SHACL rules."@en ;
    owl:inverseOf :validates .

:validates a owl:ObjectProperty ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "validates"@en ;
    rdfs:comment "Inverse of isValidatedBy."@en ;
    owl:inverseOf :isValidatedBy .

:assignedToBusinessProcess a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "assigned to business process"@en ;
    rdfs:comment "Links an invoice message to its business process context."@en ;
    owl:inverseOf :isBusinessProcessOf .

:isBusinessProcessOf a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is business process of"@en ;
    rdfs:comment "Inverse of assignedToBusinessProcess."@en ;
    owl:inverseOf :assignedToBusinessProcess .

#################################################################
# Data Properties
#################################################################
:hasInvoiceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range xsd:decimal ;
    rdfs:label "has invoice amount"@en ;
    rdfs:comment "The total invoice amount in the summary section."@en .

:hasInvoiceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice number"@en ;
    rdfs:comment "The invoice number in the header section."@en .

:hasDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has date"@en ;
    rdfs:comment "The date of the invoice in the header section."@en .

:hasReferenceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has reference number"@en ;
    rdfs:comment "The reference number in the header section."@en .

#################################################################
# Restrictions and Complex Axioms
#################################################################
# RoleAssignment reification pattern
:RoleAssignment a owl:Class ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasRole ; owl:someValuesFrom :PartyRole ] ,
                    [ a owl:Restriction ; owl:onProperty :inInvoice ; owl:someValuesFrom :InvoiceMessage ] .

# Disjointness
:Organization owl:disjointWith :Item, :Address .
:BuyerRole owl:disjointWith :DeliveryPartyRole .

# All items in DetailSection must have Price and Quantity
:Item a owl:Class ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasPrice ; owl:allValuesFrom :Price ] ,
                    [ a owl:Restriction ; owl:onProperty :hasQuantity ; owl:allValuesFrom :Quantity ] .

# All addresses are either headquarters or warehouse addresses
:Address owl:equivalentClass [ a owl:Class ;
    owl:unionOf ( :HeadquartersAddress :WarehouseAddress )
] .

#################################################################
# Annotations for EDIFACT segment/element structure and code mappings
#################################################################
:Segment rdfs:seeAlso :EDIFACTDirectory .
:CompositeDataElement rdfs:seeAlso :EDIFACTDirectory .
:SimpleDataElement rdfs:seeAlso :EDIFACTDirectory .

#################################################################
# Alignment classes
#################################################################
:EN16931Alignment a owl:Class ;
    rdfs:label "EN 16931 Alignment"@en ;
    rdfs:comment "Alignment with the European Standard EN 16931-1 for semantic interoperability."@en .

:P2POAlignment a owl:Class ;
    rdfs:label "P2P-O Alignment"@en ;
    rdfs:comment "Alignment with the Purchase-to-Pay Ontology (P2P-O)."@en .

